var args = new SocketAsyncEventArgs();
args.SetBuffer(buffer, 0, buffer.Length);
args.Completed += OnCompleted;          // invoked on the thread pool

// one outstanding accept per listening socket
if (!listener.AcceptAsync(acceptArgs)) OnCompleted(listener, acceptArgs);

static void OnCompleted(object? sender, SocketAsyncEventArgs e)
{
    if (e.SocketError == SocketError.Success && e.BytesTransferred > 0)
        ((Socket)sender!).ReceiveAsync(e);   // rearm only from the callback
}
